{
  "goblin_camp": {
    "location": {
      "description": "Hidden deep within the dense forest, the goblin camp lies in a secluded clearing, far from the eyes of travelers or adventurers."
    },
    "appearance": {
      "description": "The camp is a chaotic mix of rough-hewn tents, branch-and-skin shelters, and small crackling fires. The air is thick with smoke and constant activity as goblins hunt, barter, and tinker with strange, handcrafted devices."
    },
    "mobility": {
      "description": "The camp is ever-changing, with no permanent structures. Goblins value mobility, always ready to pack up and move in search of resources or safety."
    },
    "defenses": {
      "description": "The camp's perimeter is protected by makeshift barricades and traps—sharpened sticks, tripwires, and camouflaged pits to ward off intruders."
    },
    "goblin_traits": {
      "description": "The goblins are mischievous, resourceful, and quick-witted. Scavenging is their specialty, transforming found materials into tools, weapons, or magical trinkets. Their unpolished creations, such as poisoned darts or enchanted curiosities, are surprisingly effective."
    },
    "fire_pit": {
      "description": "At the camp's heart is a large fire pit where goblins gather each night to share stories, cook meals, and plan their next schemes. The leader, the strongest or most cunning goblin, sits here giving orders and striking deals."
    },
    "community": {
      "description": "Despite their unruly appearance, the goblin camp is a tight-knit community. Every goblin has a role—scout, scavenger, trapper, or cook—and they fiercely look out for one another. Thriving on adventure and chaos, the goblins are always ready for their next exploit."
    }
  }
}

